\label{defn_of_disc}


	Let $A,K$ be commutative rings with $K$ and $A$-algebra. let $B=\{b_1,\dots,b_n\}$ be a set of elements in $K$. The discriminant of $B$ is defined as \[\Delta(B)=  \det \left (\begin{matrix} \operatorname{Tr}_{K/A}(b_1b_1) &\cdots& \operatorname{Tr}_{K/A}(b_1b_n)\\ \vdots & & \vdots \\  \operatorname{Tr}_{K/A}(b_nb_1) &\cdots& \operatorname{Tr}_{K/A}(b_nb_n)
	\end{matrix} \right ).\]

\label{lemma:disc_via_embs}



	Let $K$ be a number field with basis $B=\{b_1,\dots,b_n\}$ and let $\sigma_1,\dots,\sigma_n$ be the embeddings of $K$ into $\mathbb{C}$. Now let $M$ be the matrix  \[\left (\begin{matrix} \sigma_1(b_1) &\cdots& \sigma_1(b_n)\\ \vdots & & \vdots \\  \sigma_n(b_1) &\cdots& \sigma_n(b_n)
	\end{matrix} \right ).\] Then \[\Delta(B)=\det(M)^2.\]

\label{lem:flt_ideals_coprime}



	Let $p \geq 5$ be an prime number, $\zeta_p$ a $p$-th root of unity and $x, y \in \mathbb{Z}$ coprime.

	For $i \neq j$ with $i,j \in {0,\dots,p-1}$ we can write \[(\zeta_p^i-\zeta_p^j)=u(1-\zeta_p)\] with $u$ a unit in $\mathbb{Z}[\zeta_p]$. From this it follows that the ideals \[(x+y),(x+\zeta_py),(x+\zeta_p^2y),\dots,(x+\zeta_p^{p-1}y)\] are pairwise coprime.

\label{lemma:may_assume_coprime}




	Let $p \geq 3$ be an prime number, $\zeta_p$ a $p$-th root of unity and $K=\mathbb{Q}(\zeta_p)$.  Assume that we have $x,y,z \in \mathbb{Z}$ with $\gcd(xyz,p)=1$ and such that \[x^p+y^p=z^p.\]

	This is the so called "case I". To prove Fermat's last theorem, we may assume that:
	\begin{itemize}
		\item $p \geq 5$;
		\item $x,y,z$ are pairwise coprime;
		\item $x \not \equiv y \mod p$.
	\end{itemize}

\label{lem:gen_ideal_coprimality}
		Let $p$ be a regular odd prime, $x,y,z,\epsilon \in \mathbb{Z}[\zeta_p]$, $\epsilon$ a unit, and $n \in \mathbb{Z}_{\geq 1}$. Assume $x,y,z$ are coprime to $(1-\zeta_p)$,  $x^p+y^p+\epsilon(1-\zeta_p)^{pn}z^p=0$ and $x+y$ is divisible by $\mathfrak{p}^2$ and $x+ \zeta_p^ky$ is only divisible by $\mathfrak{p}=(1-\zeta_p)$ (for $0 < k \leq p-1$).
		Let $\mathfrak{m}= \mathrm{gcd}((x),(y))$. Then:
		\begin{enumerate}
			\item We can write 	\[(x+y)=\mathfrak{p}^{p(m-1)+1}\mathfrak{m}\mathfrak{c}_0\] and \[ (x+\zeta_p^k y)=\mathfrak{p}\mathfrak{m}\mathfrak{c}_k \] (for $0 < k \leq p-1$) where $m=n(p-1)$ and with $\mathfrak{c}_i$ pairwise coprime.
			\item Each $\mathfrak{c}_k=\mathfrak{a}_k^p$ and $\mathfrak{a}_k\mathfrak{a}_0^{-1}$ is principal (as a fractional ideal).
		\end{enumerate}

\label{def:rel_different}

    Let $K, F$ be number fields with $F \subseteq K$. Let  $A$ be an additive subgroup of $K$. Let \[A^{-1}=\{ \alpha \in K | \alpha A \in \mathcal{O}_K\}\] and
    \[A^* = \{ \alpha \in K | \operatorname{Tr}_{K/F} (\alpha A) \in \mathcal{O}_F\}.\] The relative different $\mathfrak{d}_{K/F}$ of $K/F$ is then defined as $((\mathcal{O}_K)^*)^{-1}$ which one checks is an integral ideal in $\mathcal{O}_K$. This is also the annihilator of $\Omega^1_{\mathcal{O}_K/\mathcal{O}_F}$ if we want to be fancy.
